//! Generated by `scripts/AbilityGenerator.py` from `data/abilities.csv` and
//! `data/ability_effects.csv` — edit the CSVs and re-run the generator.
//!
//! Each function returns a normal [`AbilityDefinition`]; these take precedence over
//! hand-written definitions in `catalog.rs` for the same [`AbilityId`].

#[allow(unused_imports)]
use super::catalog::{nova_ring, shockwave_ring};
#[allow(unused_imports)]
use super::definition::{
    AbilityBehavior, AbilityDefinition, AbilityEffect, AbilityMechanic, AbilityTrigger, AreaCenter,
    AreaRadius, Attribute, Condition, DisplacementKind, EffectScaling, EffectTarget,
    LeashAnchorKind, PassiveStat, RankValue, StatusFilter, StatusSpec, TargetTeam, TargetType,
};
#[allow(unused_imports)]
use crate::components::{AbilityId, DamageType};
#[allow(unused_imports)]
use crate::scale;
#[allow(unused_imports)]
use crate::status::{DispelStrength, StatusKind};
#[allow(unused_imports)]
use crate::vitals::{ResourceKind, ResourceStat};

/// CSV-authored definition for `id`, if any.
pub fn definition(id: AbilityId) -> Option<AbilityDefinition> {
    match id {
        AbilityId::SeismicSlam => Some(seismic_slam()),
        AbilityId::ArcaneLance => Some(arcane_lance()),
        AbilityId::Cataclysm => Some(cataclysm()),
        AbilityId::StoneSkin => Some(stone_skin()),
        AbilityId::Overcharge => Some(overcharge()),
        AbilityId::Blink => Some(blink()),
        AbilityId::ShadowStrike => Some(shadow_strike()),
        AbilityId::QueenOfPainBlink => Some(queen_of_pain_blink()),
        AbilityId::ScreamOfPain => Some(scream_of_pain()),
        AbilityId::SonicWave => Some(sonic_wave()),
        AbilityId::MagnusShockwave => Some(magnus_shockwave()),
        AbilityId::Empower => Some(empower()),
        AbilityId::Skewer => Some(skewer()),
        AbilityId::ReversePolarity => Some(reverse_polarity()),
        AbilityId::Shrapnel => Some(shrapnel()),
        AbilityId::Headshot => Some(headshot()),
        AbilityId::TakeAim => Some(take_aim()),
        AbilityId::Assassinate => Some(assassinate()),
        AbilityId::Earthshock => Some(earthshock()),
        AbilityId::Overpower => Some(overpower()),
        AbilityId::FurySwipes => Some(fury_swipes()),
        AbilityId::Enrage => Some(enrage()),
        AbilityId::DarkPact => Some(dark_pact()),
        AbilityId::Pounce => Some(pounce()),
        AbilityId::EssenceShift => Some(essence_shift()),
        AbilityId::ShadowDance => Some(shadow_dance()),
        _ => None,
    }
}

// <ability:seismic_slam>
